/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ConfigurationsScreen } from "../../src/configurations/ConfigurationsScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { OrbitsScreen } from "../../src/orbits/OrbitsScreen.js";
import PlanetaryConfigurationsColors from "../../src/PlanetaryConfigurationsColors.js";
import { PeriodsScreen } from "../../src/periods/PeriodsScreen.js";
import { PlanetaryConfigurationsPreferencesModel } from "../../src/preferences/PlanetaryConfigurationsPreferencesModel.js";
import { PtolemaicScreen } from "../../src/ptolemaic/PtolemaicScreen.js";
import { SynodicMotionScreen } from "../../src/synodic/SynodicMotionScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  const simPreferences = new PlanetaryConfigurationsPreferencesModel(Tandem.ROOT.createTandem("preferences"));
  const screens = [
    new OrbitsScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().orbitsStringProperty,
      tandem: Tandem.ROOT.createTandem("orbitsScreen"),
      backgroundColorProperty: PlanetaryConfigurationsColors.backgroundColorProperty,
    }),
    new ConfigurationsScreen({
      name: stringManager.getScreenNames().configurationsStringProperty,
      tandem: Tandem.ROOT.createTandem("configurationsScreen"),
      backgroundColorProperty: PlanetaryConfigurationsColors.backgroundColorProperty,
    }),
    new SynodicMotionScreen({
      name: stringManager.getScreenNames().synodicStringProperty,
      tandem: Tandem.ROOT.createTandem("synodicScreen"),
      backgroundColorProperty: PlanetaryConfigurationsColors.backgroundColorProperty,
    }),
    new PeriodsScreen({
      name: stringManager.getScreenNames().periodsStringProperty,
      tandem: Tandem.ROOT.createTandem("periodsScreen"),
      backgroundColorProperty: PlanetaryConfigurationsColors.backgroundColorProperty,
    }),
    new PtolemaicScreen({
      name: stringManager.getScreenNames().ptolemaicStringProperty,
      tandem: Tandem.ROOT.createTandem("ptolemaicScreen"),
      backgroundColorProperty: PlanetaryConfigurationsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { PlanetaryConfigurationsColors, stringManager } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
